abstract class Media{abstract double lateFee(int days);}class Book extends Media{double lateFee(int d){return d*2.0;}}class DVD extends Media{double lateFee(int d){return d*5.0;}}class Game extends Media{double lateFee(int d){return d*8.0;}}public class MediaFees{public static void main(String[]x){Media[] a={new Book(),new DVD(),new Game()};double sum=0;for(Media m:a){double f=m.lateFee(3);System.out.println(m.getClass().getSimpleName()+": "+f);sum+=f;}System.out.println("Total fees="+sum);}}
